/* Microfix 3.8.39: whole project title toggles accordion; Layers header uses collapse arrow */
(()=>{
  const panel=document.getElementById("layersPanel"),head=panel?.querySelector(".panel-head"),titleBox=head?.querySelector(".layers-project-titlebox"),menuToggle=document.getElementById("layersProjectMenuToggle");
  if(!panel||!head)return;
  if(titleBox&&menuToggle&&!titleBox.dataset.projectAccordionHitarea){
    titleBox.dataset.projectAccordionHitarea="1";
    titleBox.setAttribute("role","button");
    titleBox.tabIndex=0;
    const activate=e=>{
      if(e.type==="keydown"&&!(["Enter"," "].includes(e.key)))return;
      if(e.target.closest?.("#layersProjectMenuToggle"))return;
      e.preventDefault();
      menuToggle.click();
    };
    titleBox.addEventListener("click",activate);
    titleBox.addEventListener("keydown",activate);
  }
  const oldClose=head.querySelector('[data-close="layersPanel"]');
  if(oldClose&&!document.getElementById("layersCollapse")){
    const collapse=oldClose.cloneNode(true);
    collapse.id="layersCollapse";
    collapse.removeAttribute("data-close");
    collapse.title=state.language==="ru"?"Свернуть панель слоёв":"Collapse Layers";
    collapse.innerHTML='<svg><use href="#i-arrow"/></svg>';
    oldClose.replaceWith(collapse);
    collapse.addEventListener("click",e=>{
      e.preventDefault();e.stopPropagation();
      state.ui.layersCollapsed=!panel.classList.contains("collapsed");
      panel.classList.toggle("collapsed",!!state.ui.layersCollapsed);
      queuePersist();
    });
  }
  panel.classList.toggle("collapsed",!!state.ui.layersCollapsed);
  const topToggle=document.getElementById("layersToggle");
  if(topToggle&&!topToggle.dataset.layersFullToggleFix){
    topToggle.dataset.layersFullToggleFix="1";
    topToggle.addEventListener("click",()=>setTimeout(()=>{
      if(state.layersOpen){state.ui.layersCollapsed=false;panel.classList.remove("collapsed");queuePersist()}
    },0));
  }
})();

/* Microfix 3.8.39: clickable project title + Figma-like Layers collapse rail */
.layers-project-titlebox{cursor:pointer!important;border-radius:8px!important;padding:2px 3px!important;margin:-2px -3px!important}
.layers-project-titlebox:hover{background:color-mix(in srgb,var(--surface-2) 70%,transparent)!important}
.layers-project-titlebox:focus-visible{outline:2px solid var(--accent)!important;outline-offset:2px!important}
.layers-panel{transition:width .2s ease,transform .22s cubic-bezier(.2,.8,.2,1),opacity .22s!important}
.layers-panel.collapsed{width:56px!important;min-width:56px!important}
.layers-panel.collapsed .panel-resizer{display:none!important}
.layers-panel.collapsed .panel-head>div,.layers-panel.collapsed #projectPopover,.layers-panel.collapsed .panel-tabs,.layers-panel.collapsed .panel-search,.layers-panel.collapsed .layer-list,.layers-panel.collapsed .panel-footer{display:none!important}
.layers-panel.collapsed .panel-head{padding:10px 7px!important;justify-content:center!important;min-height:58px!important;border-bottom:0!important}
#layersCollapse svg{transition:transform .18s ease!important;transform:rotate(180deg)!important}
.layers-panel.collapsed #layersCollapse svg{transform:rotate(0deg)!important}
#layersCollapse{display:grid!important;place-items:center!important}
